/// How icon_shift_cli recognizes files it created. Files written by the
/// earlier `icon_shift_generator` name are still recognized.
const toolName = 'icon_shift_cli';
const generatedMarker = 'Generated by $toolName';
const _legacyMarkers = ['Generated by icon_shift_generator'];

const iosAuthor = toolName;
const _legacyIosAuthors = {'icon_shift_generator'};

const dartHeader =
    '// GENERATED by $toolName from icon_shift.yaml. Do not edit.';
const _legacyDartHeaders = [
  '// GENERATED by icon_shift_generator from icon_shift.yaml. Do not edit.',
];

bool hasGeneratedMarker(String content) =>
    content.contains(generatedMarker) || _legacyMarkers.any(content.contains);

bool isOwnIosAuthor(Object? author) =>
    author == iosAuthor || _legacyIosAuthors.contains(author);

bool hasDartHeader(String content) =>
    content.startsWith(dartHeader) ||
    _legacyDartHeaders.any(content.startsWith);
